// Implementation sketch for DSU with rollback and segment-tree processing
class DSURollback { constructor(n){ this.parent=Array.from({length:n},(_,i)=>i); this.rank=Array(n).fill(0); this.changes=[]; this.components=n; }
find(x){ while(this.parent[x]!=x){ x=this.parent[x]; } return x; }
union(a,b){ a=this.find(a); b=this.find(b); if(a==b){ this.changes.push(null); return; } if(this.rank[a]<this.rank[b]){ [a,b]=[b,a]; }
 this.changes.push([b,this.parent[b],this.rank[a]]); this.parent[b]=a; if(this.rank[a]==this.rank[b]) this.rank[a]++; this.components--; }
rollback(){ const c=this.changes.pop(); if(!c) return; if(c===null) return; const [b, oldParent, oldRank] = c; this.parent[b]=oldParent; // restore rank by computing root if needed (simplified) this.components++; }
}

// Segment-tree over time with edge intervals and queryTimes
```

